// Разбираем событие GitHub и решаем, нужно ли ревью и какой моделью.
// mode = 'main'  -> основная модель (OpenAI), с проверкой Data Table
// mode = 'other' -> вторая модель (DeepSeek), команда /make_other_ai_review
const MAIN_MODEL = 'openai/gpt-5.2';
const OTHER_MODEL = 'deepseek-flash';

const out = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const b = item.json.body || {};
  const event = headers['x-github-event']
    || (b.comment ? 'issue_comment' : (b.pull_request ? 'pull_request' : 'unknown'));
  const repo = b.repository && b.repository.full_name;

  // 1) PR открыт -> основное ревью
  if (event === 'pull_request' && b.action === 'opened') {
    out.push({ json: {
      mode: 'main', trigger: 'pr_opened', model: MAIN_MODEL, repo,
      pr_number: b.number, pr_url: b.pull_request.html_url,
    }});
    continue;
  }

  // 2) Комментарий к PR с командой
  if (event === 'issue_comment' && b.action === 'created' && b.issue && b.issue.pull_request) {
    const command = ((b.comment && b.comment.body) || '').trim().split(/\s+/)[0];
    const base = {
      trigger: 'command', command, repo, pr_number: b.issue.number,
      pr_url: b.issue.pull_request.html_url || b.issue.html_url,
      comment_author: b.comment.user && b.comment.user.login,
    };
    if (command === '/make_ai_review') {
      out.push({ json: { ...base, mode: 'main', model: MAIN_MODEL } });
    } else if (command === '/make_other_ai_review') {
      out.push({ json: { ...base, mode: 'other', model: OTHER_MODEL } });
    }
  }
}
// Пустой результат = событие нас не интересует, выполнение на этом заканчивается.
return out;

// Разбиваем unified diff на блоки изменённого кода.
// Блок = непрерывная последовательность строк +/- внутри одного hunk.
// Длинные блоки режем по началу функций/классов, чтобы комментарии были точечными.
const ctx = $('Route event').first().json;
const pr = $('Get PR').first().json;
const diff = String($input.first().json.data || '');

const SPLIT_AT = 12;   // после стольких строк блок можно разрезать на def/class
const HARD_MAX = 60;   // жёсткий максимум строк в блоке
const MAX_BLOCKS = 25; // ограничение на число запросов к модели
const CONTEXT = 3;     // строк контекста перед блоком
const GAP = 3;         // изменения, разделённые <= GAP строками контекста, — один блок

const blocks = [];
let path = null, inHunk = false, oldLine = 0, newLine = 0;
let cur = null, ctxBuf = [], gap = [];

function flush() {
  gap = [];
  if (cur && cur.lines.length) {
    const added = cur.lines.filter(l => l.sign === '+');
    const removed = cur.lines.filter(l => l.sign === '-');
    let side, start, end;
    if (added.length) {
      side = 'RIGHT'; start = added[0].newNo; end = added[added.length - 1].newNo;
    } else {
      side = 'LEFT'; start = removed[0].oldNo; end = removed[removed.length - 1].oldNo;
    }
    const fmt = l => `${String(l.sign === '-' ? l.oldNo : l.newNo).padStart(4)} ${l.sign} ${l.code}`;
    blocks.push({
      path, side, start_line: start, line: end,
      added: added.length, removed: removed.length,
      text: [...cur.context.map(fmt), ...cur.lines.map(fmt)].join('\n'),
    });
  }
  cur = null;
}

for (const raw of diff.split('\n')) {
  if (raw.startsWith('diff --git')) { flush(); inHunk = false; path = null; ctxBuf = []; continue; }
  if (!inHunk) {
    if (raw.startsWith('+++ ')) {
      const p = raw.slice(4).trim();
      path = p === '/dev/null' ? null : p.replace(/^b\//, '');
    }
    if (raw.startsWith('@@')) {
      const m = raw.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
      if (m) { oldLine = +m[1]; newLine = +m[2]; inHunk = true; ctxBuf = []; }
    }
    continue;
  }
  if (raw.startsWith('@@')) {
    flush();
    const m = raw.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (m) { oldLine = +m[1]; newLine = +m[2]; ctxBuf = []; }
    continue;
  }
  if (raw.startsWith('\\')) continue; // "\ No newline at end of file"
  const sign = raw[0] === '+' || raw[0] === '-' ? raw[0] : ' ';
  const code = raw.slice(1);
  const line = { sign, code, oldNo: oldLine, newNo: newLine };

  if (sign === ' ') {
    // Короткий разрыв (<= GAP строк контекста) не разрывает блок
    if (cur) {
      gap.push(line);
      if (gap.length > GAP) { flush(); ctxBuf = gap.slice(-CONTEXT); gap = []; }
    } else {
      ctxBuf.push(line); if (ctxBuf.length > CONTEXT) ctxBuf.shift();
    }
    oldLine++; newLine++;
    continue;
  }
  if (!path) { if (sign === '-') oldLine++; else newLine++; continue; } // удалённый файл
  if (cur && gap.length) { cur.lines.push(...gap); gap = []; }
  const startsDef = sign === '+' && /^ {0,4}(async\s+def|def|class)\b|^ {0,4}@\w/.test(code);
  if (cur && ((startsDef && cur.lines.length >= SPLIT_AT) || cur.lines.length >= HARD_MAX)) {
    const tail = cur.lines.slice(-CONTEXT);
    flush();
    ctxBuf = tail;
  }
  if (!cur) cur = { context: ctxBuf.slice(), lines: [] };
  cur.lines.push(line);
  if (sign === '-') oldLine++; else newLine++;
}
flush();

return blocks.slice(0, MAX_BLOCKS).map((b, i) => ({ json: {
  ...b, index: i + 1, total: Math.min(blocks.length, MAX_BLOCKS),
  mode: ctx.mode, model: ctx.model, repo: ctx.repo, pr_number: ctx.pr_number,
  head_sha: pr.head.sha,
}}));

// Собираем один review с точечными комментариями к каждому блоку.
const ctx = $('Route event').first().json;
const pr = $('Get PR').first().json;
const blocks = $('Split diff into blocks').all().map(i => i.json);
const outputs = $input.all().map(i => String(i.json.output ?? i.json.text ?? '').trim());
const modelLabel = ctx.mode === 'other' ? `DeepSeek (${ctx.model})` : `OpenAI (${ctx.model})`;

let withIssues = 0;
const comments = blocks.map((b, i) => {
  const text = outputs[i] || '';
  const ok = !text || /^LGTM[.!]?$/i.test(text);
  if (!ok) withIssues++;
  const c = {
    path: b.path,
    side: b.side,
    line: b.line,
    body: (ok ? '✅ Замечаний к этому блоку нет.' : text) + `\n\n<sub>🤖 ${modelLabel} · блок ${b.index}/${b.total}</sub>`,
  };
  if (b.start_line && b.start_line < b.line) { c.start_line = b.start_line; c.start_side = b.side; }
  return c;
});

const body = [
  `## 🤖 AI code review — ${modelLabel}`,
  '',
  blocks.length
    ? `Проверено блоков изменённого кода: **${blocks.length}**, с замечаниями: **${withIssues}**. Комментарии оставлены к конкретным строкам.`
    : 'В diff не найдено изменённого кода для ревью.',
  '',
  `<sub>Запуск: ${ctx.trigger === 'command' ? '`' + ctx.command + '`' : 'открытие PR'}</sub>`,
].join('\n');

return [{ json: { commit_id: pr.head.sha, event: 'COMMENT', body, comments } }];
